// ---- object NarrowBody — one definition, a generated family per target (SPEC §4.8) ----

// NarrowBodyState — the full simulation struct: every field
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct NarrowBodyState {
    pub position: FixedVec,
    pub rotation: FixedQuat,
    pub velocity: FixedVec,
}

// The zero form (SPEC §5): specified defaults live only in new(), never here.
impl Default for NarrowBodyState {
    fn default() -> Self {
        NarrowBodyState {
            position: FixedVec::default(),
            rotation: FixedQuat::default(),
            velocity: FixedVec::default(),
        }
    }
}

// NarrowBodyData_Deep — every non-[local] field, deep encodings: full state for
// client-side prediction
#[allow(non_camel_case_types)] // the name is fixed across targets (SPEC §4.8)
#[derive(Clone, Copy, PartialEq, Debug)]
