pub const NARROW_BODY_DATA_SHALLOW_MAX_BITS: u64 = 228;
pub const NARROW_BODY_DATA_SHALLOW_MAX_BYTES: usize = 32; // rounded up to the 8-byte write-buffer granularity

#[inline]
pub fn write_narrow_body_data_shallow(stream: &mut WriteStream<'_>, value: &NarrowBodyData_Shallow) -> Result {
    debug_assert!(value.position_x >= -25600000_i32 && value.position_x <= 25600000_i32);
    {
        let mut offset_value = (value.position_x as u32).wrapping_sub((-25600000_i32) as u32);
        stream.serialize_bits(&mut offset_value, 26)?;
    }
    debug_assert!(value.position_y >= -25600000_i32 && value.position_y <= 25600000_i32);
    {
        let mut offset_value = (value.position_y as u32).wrapping_sub((-25600000_i32) as u32);
        stream.serialize_bits(&mut offset_value, 26)?;
    }
    debug_assert!(value.position_z >= -25600000_i32 && value.position_z <= 25600000_i32);
    {
        let mut offset_value = (value.position_z as u32).wrapping_sub((-25600000_i32) as u32);
        stream.serialize_bits(&mut offset_value, 26)?;
    }
    debug_assert!(value.rotation_x >= -1024_i16 && value.rotation_x <= 1024_i16);
    {
        let mut offset_value = (value.rotation_x as u32).wrapping_sub((-1024_i32) as u32);
        stream.serialize_bits(&mut offset_value, 12)?;
    }
    debug_assert!(value.rotation_y >= -1024_i16 && value.rotation_y <= 1024_i16);
    {
        let mut offset_value = (value.rotation_y as u32).wrapping_sub((-1024_i32) as u32);
        stream.serialize_bits(&mut offset_value, 12)?;
    }
    debug_assert!(value.rotation_z >= -1024_i16 && value.rotation_z <= 1024_i16);
    {
        let mut offset_value = (value.rotation_z as u32).wrapping_sub((-1024_i32) as u32);
        stream.serialize_bits(&mut offset_value, 12)?;
    }
    debug_assert!(value.rotation_w >= -1024_i16 && value.rotation_w <= 1024_i16);
    {
        let mut offset_value = (value.rotation_w as u32).wrapping_sub((-1024_i32) as u32);
        stream.serialize_bits(&mut offset_value, 12)?;
    }
    write_fixed_vec(stream, &value.velocity)?;
    Ok(())
}

#[inline]
pub fn read_narrow_body_data_shallow(stream: &mut ReadStream<'_>, value: &mut NarrowBodyData_Shallow) -> Result {
    stream.serialize_int(&mut value.position_x, -25600000_i32, 25600000_i32)?;
    stream.serialize_int(&mut value.position_y, -25600000_i32, 25600000_i32)?;
    stream.serialize_int(&mut value.position_z, -25600000_i32, 25600000_i32)?;
    {
        let mut component_value: i32 = 0;
        stream.serialize_int(&mut component_value, -1024_i32, 1024_i32)?;
        value.rotation_x = component_value as i16;
    }
    {
        let mut component_value: i32 = 0;
        stream.serialize_int(&mut component_value, -1024_i32, 1024_i32)?;
        value.rotation_y = component_value as i16;
    }
    {
        let mut component_value: i32 = 0;
        stream.serialize_int(&mut component_value, -1024_i32, 1024_i32)?;
        value.rotation_z = component_value as i16;
    }
    {
        let mut component_value: i32 = 0;
        stream.serialize_int(&mut component_value, -1024_i32, 1024_i32)?;
        value.rotation_w = component_value as i16;
    }
    read_fixed_vec(stream, &mut value.velocity)?;
    Ok(())
}

pub fn quantize_narrow_body(input: &NarrowBodyData_Interpolate, output: &mut NarrowBodyData_Shallow) {
    {
        let raw = input.position.x as i64;
        output.position_x = (if raw >= 0 { (raw + 128) >> 8 } else { -((-raw + 128) >> 8) }) as i32;
    }
    {
        let raw = input.position.y as i64;
        output.position_y = (if raw >= 0 { (raw + 128) >> 8 } else { -((-raw + 128) >> 8) }) as i32;
    }
    {
        let raw = input.position.z as i64;
        output.position_z = (if raw >= 0 { (raw + 128) >> 8 } else { -((-raw + 128) >> 8) }) as i32;
    }
    {
        let raw = input.rotation.x as i64;
        output.rotation_x = (if raw >= 0 { (raw + 524288) >> 20 } else { -((-raw + 524288) >> 20) }) as i16;
    }
    {
        let raw = input.rotation.y as i64;
        output.rotation_y = (if raw >= 0 { (raw + 524288) >> 20 } else { -((-raw + 524288) >> 20) }) as i16;
    }
    {
        let raw = input.rotation.z as i64;
        output.rotation_z = (if raw >= 0 { (raw + 524288) >> 20 } else { -((-raw + 524288) >> 20) }) as i16;
    }
    {
        let raw = input.rotation.w as i64;
        output.rotation_w = (if raw >= 0 { (raw + 524288) >> 20 } else { -((-raw + 524288) >> 20) }) as i16;
    }
    output.velocity = input.velocity;
}

pub fn unquantize_narrow_body(input: &NarrowBodyData_Shallow, output: &mut NarrowBodyData_Interpolate) {
    output.position.x = ((input.position_x as i64) << 8) as i64;
    output.position.y = ((input.position_y as i64) << 8) as i64;
    output.position.z = ((input.position_z as i64) << 8) as i64;
    output.rotation.x = ((input.rotation_x as i64) << 20) as i32;
    output.rotation.y = ((input.rotation_y as i64) << 20) as i32;
    output.rotation.z = ((input.rotation_z as i64) << 20) as i32;
    output.rotation.w = ((input.rotation_w as i64) << 20) as i32;
    output.velocity = input.velocity;
}

// The message tag wire: MessageType in [0, 1], minimal bits; None = 0 is a
// valid wire value meaning *no message* — the stream terminator (SPEC §4.8).
#[inline]
pub fn write_message_type(stream: &mut WriteStream<'_>, value: MessageType) -> Result {
    debug_assert!(value.0 as u32 <= 1); // the runtime ranged form's write assert, kept (debug parity)
    {
        let mut offset_value = value.0 as u32;
        stream.serialize_bits(&mut offset_value, 1)?;
    }
    Ok(())
}

#[inline]
pub fn read_message_type(stream: &mut ReadStream<'_>, value: &mut MessageType) -> Result {
    let mut tag_value: i32 = 0;
    stream.serialize_int(&mut tag_value, 0, 1)?;
    *value = MessageType(tag_value as u8);
    Ok(())
}

// The message-level bound: the tag plus the largest message (SPEC §6.1);
// MESSAGE_MAX_BYTES is rounded up to the 8-byte write-buffer granularity.
pub const MESSAGE_MAX_BITS: u64 = 1206;
pub const MESSAGE_MAX_BYTES: usize = 152;

// Message is the dispatch surface: the tagged union over the message set —
// a Rust enum IS that union (stack storage, size = the largest message plus
// the tag; nothing heap-allocates per message, SPEC §6.1). Message::None is
// the stream terminator (SPEC §4.8).
#[derive(Clone, Copy, PartialEq, Debug)]
#[allow(clippy::large_enum_variant)]
pub enum Message {
    None,
    LudicrousState(LudicrousState),
}

#[inline]
pub fn write_message(stream: &mut WriteStream<'_>, message: &Message) -> Result {
    match message {
        Message::None => write_message_type(stream, MessageType::NONE), // the stream terminator (SPEC §4.8)
        Message::LudicrousState(value) => {
            write_message_type(stream, MessageType::LUDICROUS_STATE)?;
            write_ludicrous_state(stream, value)
        }
    }
}

// read_message_into decodes the next message into caller-owned storage: the
// variant is reset to its zero form (SPEC §5), then its fields decode in
// place — no per-message copy of the union out of the call. On error the
// storage holds the partially decoded zero form: discard it.
//
// Choosing a read surface: read_message for one-shot by-value reads;
// read_message_into for reuse loops — hoist ONE Message and read every
// message into it (the Go/C# MessageStorage discipline). Reuse removes the
// per-message copy-out of the union and measured 2.6x on the steady-state
// batch read (M2, 2026-08-06). The two surfaces stay separate on purpose —
// see the note on read_message.
#[inline]
pub fn read_message_into(stream: &mut ReadStream<'_>, message: &mut Message) -> Result {
    let mut tag_value = MessageType::NONE;
    read_message_type(stream, &mut tag_value)?;
    match tag_value {
        MessageType::NONE => {
            *message = Message::None; // the stream terminator (SPEC §4.8)
            Ok(())
        }
        MessageType::LUDICROUS_STATE => {
            *message = Message::LudicrousState(LudicrousState::default()); // reused storage starts from the zero form, as the union does
            let Message::LudicrousState(value) = message else {
                unreachable!()
            };
            read_ludicrous_state(stream, value)
        }
        // read_message_type already rejected tags past the set; the match
        // still needs the arm because tag constants are never exhaustive
        _ => Err(Error::Validation),
    }
}

// read_message decodes the next message by value — the one-shot surface.
// It deliberately does NOT delegate to read_message_into: routing the
// return through a &mut out-param defeated LLVM's in-place construction
// of the returned union and cost the batch read 23% (measured M2,
// 2026-08-06). Both surfaces stay; reuse loops call read_message_into.
#[inline]
pub fn read_message(stream: &mut ReadStream<'_>) -> Result<Message> {
    let mut tag_value = MessageType::NONE;
    read_message_type(stream, &mut tag_value)?;
    match tag_value {
        MessageType::NONE => Ok(Message::None), // the stream terminator (SPEC §4.8)
        MessageType::LUDICROUS_STATE => {
            let mut value = LudicrousState::default();
            read_ludicrous_state(stream, &mut value)?;
            Ok(Message::LudicrousState(value))
        }
        // read_message_type already rejected tags past the set; the match
        // still needs the arm because tag constants are never exhaustive
        _ => Err(Error::Validation),
    }
}

// The object tag wire: ObjectType in [0, 2], minimal bits; None = 0 is the
// null — the sentinel the surveyed baseline streams terminate with (SPEC §4.8).
#[inline]
pub fn write_object_type(stream: &mut WriteStream<'_>, value: ObjectType) -> Result {
    debug_assert!(value.0 as u32 <= 2); // the runtime ranged form's write assert, kept (debug parity)
    {
        let mut offset_value = value.0 as u32;
        stream.serialize_bits(&mut offset_value, 2)?;
    }
    Ok(())
}

#[inline]
pub fn read_object_type(stream: &mut ReadStream<'_>, value: &mut ObjectType) -> Result {
    let mut tag_value: i32 = 0;
    stream.serialize_int(&mut tag_value, 0, 2)?;
    *value = ObjectType(tag_value as u8);
    Ok(())
}

